class PushBoxGame:
    WALL = "#"
    PLAYER = "O"
    TARGET = "G"
    BOX = "X"

    def __init__(self, map):
        self.map = map
        self.player_row = 0
        self.player_col = 0
        self.targets = []
        self.boxes = []
        self.target_count = 0
        self.is_game_over = False

        self.init_game()

    def init_game(self):
        for row in range(len(self.map)):
            for col in range(len(self.map[row])):
                self._process_map_cell(row, col)

    def _process_map_cell(self, row, col):
        cell = self.map[row][col]
        if cell == self.PLAYER:
            self.player_row = row
            self.player_col = col
        elif cell == self.TARGET:
            self.targets.append((row, col))
            self.target_count += 1
        elif cell == self.BOX:
            self.boxes.append((row, col))

    def count_boxes_on_targets(self):
        return sum(1 for box in self.boxes if box in self.targets)

    def check_win(self):
        if self.count_boxes_on_targets() == self.target_count:
            self.is_game_over = True
        return self.is_game_over

    def _get_new_player_position(self, direction):
        new_player_row = self.player_row
        new_player_col = self.player_col

        if direction == "w":
            new_player_row -= 1
        elif direction == "s":
            new_player_row += 1
        elif direction == "a":
            new_player_col -= 1
        elif direction == "d":
            new_player_col += 1

        return new_player_row, new_player_col

    def _is_cell_walkable(self, row, col):
        return self.map[row][col] != self.WALL

    def _is_box_pushable(self, box_row, box_col, player_row, player_col):
        new_box_row = box_row + (box_row - player_row)
        new_box_col = box_col + (box_col - player_col)
        return self._is_cell_walkable(new_box_row, new_box_col)

    def _push_box(self, player_row, player_col):
        self.boxes.remove((player_row, player_col))
        new_box_row = player_row + (player_row - self.player_row)
        new_box_col = player_col + (player_col - self.player_col)
        self.boxes.append((new_box_row, new_box_col))

    def _move_player(self, new_player_row, new_player_col):
        self.player_row = new_player_row
        self.player_col = new_player_col

    def move(self, direction):
        if self.is_game_over:
            return self.is_game_over

        new_player_row, new_player_col = self._get_new_player_position(direction)

        if not self._is_cell_walkable(new_player_row, new_player_col):
            return self.check_win()

        if (new_player_row, new_player_col) in self.boxes:
            if self._is_box_pushable(new_player_row, new_player_col, self.player_row, self.player_col):
                self._push_box(new_player_row, new_player_col)
                self._move_player(new_player_row, new_player_col)
        else:
            self._move_player(new_player_row, new_player_col)

        return self.check_win()
